import type { BookingCreateInput } from '@hair-lab/contracts';
import type { BookingService } from './booking-service.js';

export async function createBooking(
  service: BookingService,
  input: BookingCreateInput,
  idempotencyKey: string,
) {
  // Ключ идемпотентности уходит в сервис: повторная отправка возвращает ту же запись.
  const booking = await service.create({ ...input, idempotencyKey });
  return booking;
}

